let securityData=null,securityLoading=null,securityGroup='reentrancy',securityVariant='attack',securityStep=0,securityEvaluationCase=null;
const securityEdits=new Map();
const securityPatterns={
 reentrancy:{name:'Reentrancy',short:'Repeated withdrawals',color:'#9480ae',icon:'M4 15h22m-7-6 7 6-7 6M9 8C4 8 2 11 2 15s2 7 7 7',
  benign:{title:'Credit cleared before payment',summary:'One withdrawal pays the authorized 10 HSK.',steps:[['Read credit','The receiver has 10 HSK of withdrawal credit.'],['Clear credit','Credit is set to zero before the external payment.'],['Pay once','The vault transfers 10 HSK to the receiver.'],['Settle balances','The vault retains 90 HSK. The receiver holds 10 HSK.']]},
  attack:{title:'Repeated withdrawal',summary:'Two callbacks reuse the same credit before it is cleared.',steps:[['Read credit','The receiver has 10 HSK of withdrawal credit.'],['Call back','The receiver re-enters withdraw while its credit is still 10 HSK.'],['Pay three times','Three payments of 10 HSK occur before the call frames clear the credit.'],['Settle balances','The vault retains 70 HSK against 90 HSK of other depositors’ claims.']]}
 },
 faulty_access_control:{name:'Access control',short:'Unauthorized transfer',color:'#b68074',icon:'M7 13V8a7 7 0 0 1 14 0v5M4 13h20v14H4zm10 5v5',
  benign:{title:'Both permissions enforced',summary:'An authorized caller pays the approved beneficiary.',steps:[['Read policy','Only Caller B may pay the fixed beneficiary, Recipient B.'],['Check caller','Caller B satisfies the role requirement.'],['Check recipient','Recipient B matches the approved beneficiary.'],['Transfer funds','The treasury pays 5 HSK to Recipient B and retains 95 HSK.']]},
  attack:{title:'Unauthorized treasury transfer',summary:'The caller and recipient both violate policy, but execution continues.',steps:[['Read policy','Only Caller B may pay the fixed beneficiary, Recipient B.'],['Bypass caller check','Caller A is not authorized. The failed check does not stop execution.'],['Bypass recipient check','Recipient A is not approved. This failed check is also bypassed.'],['Transfer funds','The treasury pays 40 HSK to Recipient A and retains 60 HSK.']]}
 },
 price_manipulation:{name:'Price manipulation',short:'Inflated collateral value',color:'#638eaa',icon:'M3 25V4m0 21h25M6 20l6-7 6 3 8-12',
  benign:{title:'Borrow against an independent price',summary:'Self-funded collateral supports a 5,000 USDT loan at 50% LTV.',steps:[['Use own funds','The borrower begins with 100 HSK. No flash funding is used.'],['Pledge collateral','100 HSK moves into lender custody. The borrower retains the collateral claim.'],['Read reference price','At the assumed price of 100 USDT/HSK and 75% maximum LTV, the borrowing limit is 7,500 USDT.'],['Borrow 5,000 USDT','Debt is 5,000 USDT against collateral valued at 10,000 USDT. Pool reserves stay unchanged.']]},
  attack:{title:'A changed pool price becomes borrowing power',summary:'The lender accepts a spot price changed within the same transaction.',steps:[['Flash funding','Borrow 100,000 USDT; principal and fee due total 100,090 USDT.'],['Move the pool price','Buy 500 HSK. Pool reserves become 500 HSK / 200,000 USDT, implying 400 USDT/HSK.'],['Pledge and borrow','Pledge 100 HSK and borrow 30,000 USDT at 75% LTV using the changed spot price.'],['Sell remaining HSK','Sell 400 HSK for 88,888.888888 USDT. Pool reserves become 900 HSK / 111,111.111112 USDT.'],['Repay flash funding','Repay 100,090 USDT. Cash remaining is 18,798.888888 USDT; 30,000 USDT debt remains.'],['Compare reference value','The assumed independent price values collateral at 10,000 USDT: 20,000 below debt. No liquidation is simulated.']]}
 }
};
// Display-only synthetic EVM identities. Original model inputs and source snapshots stay intact.
const securityAccounts={
 actor_a:{address:'0x147d889d60ce7dc2a80078f250b09ced4bdd9b2b',role:'Wallet'},
 actor_b:{address:'0xd44e6c25f495803ee6793158e49decb40281daba',role:'Authorized caller'},
 recipient_a:{address:'0xfeab81a1ef1ad1d42b5322e64fe7abf1874d64d5',role:'Recipient'},
 recipient_b:{address:'0x99de53aab3f97d1f23fd8ca51ad3765685f911fc',role:'Approved recipient'},
 initiator_a:{address:'0xda8b342359b2bf01c9c50ba0256be2fd651f6f1b',role:'Initiator'},
 toy_vault:{address:'0x937b4f8dee62605f93c581c7e5a26653d6adf3c4',role:'Vault'},
 toy_treasury:{address:'0x41d2730687ed93b3ac005455cabc13d156c64fb1',role:'Treasury'},
 toy_pool:{address:'0x62ba4f018db0afe2d64762f119d9e37e2536ce62',role:'Liquidity pool'},
 toy_lender:{address:'0x104abad7290e006c26984a42360621ef3e2caf03',role:'Lending contract'},
 toy_flash:{address:'0xd8c6fbcbef733379fb9ad66e3261302879a5518e',role:'Flash liquidity'}
};
const securityAddress=a=>securityAccounts[a]?.address||a;
const securityActor=a=>short(securityAddress(a));
function securityAccount(a){const address=securityAddress(a);return `<span class="security-account"><span class="address-cell"><span title="${esc(address)}">${securityActor(a)}</span><button class="copy-button" data-copy="${esc(address)}" aria-label="Copy address ${esc(address)}" title="Copy address">${copyIcon}</button></span><small>${esc(securityAccounts[a]?.role||'Account')}</small></span>`}
function securityText(value){let text=String(value);for(const [a,account] of Object.entries(securityAccounts))text=text.replaceAll(a,short(account.address));for(const [name,a] of Object.entries({'Caller A':'actor_a','Caller B':'actor_b','Recipient A':'recipient_a','Recipient B':'recipient_b'}))text=text.replaceAll(name,securityActor(a));return text}
const securityNumber=v=>Number(v).toLocaleString('en-US',{maximumFractionDigits:6});
function securityCurrent(){const group=securityData.groups.find(g=>g.id===securityGroup)||securityData.groups[0];securityGroup=group.id;return {group,sample:group.variants.find(v=>v.variant===securityVariant),pattern:securityPatterns[group.id]}}
function securityURL(){const p=new URLSearchParams({pattern:securityGroup,variant:securityVariant});history.replaceState(null,'','#security?'+p)}
async function loadSecurityData(){
 if(securityData)return securityData;
 try{securityLoading ||= fetch('security-data.json').then(r=>{if(!r.ok)throw Error('Scenario data unavailable');return r.json()});securityData=await securityLoading;securityData.groups.forEach(g=>g.variants.forEach(v=>{if(!securityEdits.has(v.id))securityEdits.set(v.id,{attack_labels:[...v.reference_annotation.attack_labels],notes:''})}));return securityData}catch(e){securityLoading=null;throw e}
}
async function renderSecurityCase(){
 try{await loadSecurityData()}catch{$('#security-case-content').innerHTML='<div class="empty">Unable to load case.</div>';return}
 const {group,sample,pattern}=securityCurrent(),copy={...pattern[securityVariant],steps:pattern[securityVariant].steps.map(([a,b])=>[a,securityText(b)])},isAttack=securityVariant==='attack';securityStep=Math.min(securityStep,copy.steps.length-1);
 const m=securityMetrics(group,sample),insight=securityInsights[group.id];
 $('#security-case-content').innerHTML=` <section class="security-case" style="--pattern:${pattern.color}"><div class="security-case-bar"><div class="variant-switch" aria-label="Scenario variant"><button data-security-variant="benign" aria-pressed="${!isAttack}">Baseline</button><button data-security-variant="attack" aria-pressed="${isAttack}">Attack variant</button></div></div>
 <div class="case-provenance"><span>Source template · ${securitySourceDate(group.source_transaction.timestamp)}</span><a href="${securitySourceURL(group)}" target="_blank" rel="noopener">View HSK source ↗</a></div><div class="security-case-title"><h2>${copy.title}</h2><p>${copy.summary}</p></div>
 <div class="security-metrics">${m.map(x=>`<div><span>${x.label}</span><strong>${securityNumber(x.value)}<small>${x.unit}</small></strong>${x.note?`<em>${x.note}</em>`:''}</div>`).join('')}</div>
 <div class="security-participants"><div><span>From</span>${securityAccount(sample.model_input.transaction.from)}</div><span class="participant-arrow">→</span><div><span>To</span>${securityAccount(sample.model_input.transaction.to)}</div><div><span>Method</span><code>${esc(sample.model_input.transaction.method)}</code></div></div>
 <div class="security-mechanism"><div class="mechanism-heading"><h3>${group.id==='reentrancy'?'Payment sequence':group.id==='faulty_access_control'?'Permission path':'Price and debt'}</h3><span>${isAttack?'Attack variant':'Baseline'} · Synthetic</span></div><div class="mechanism-chart">${securityDiagram(group,sample,pattern)}</div><div class="security-payments"><div class="payment-labels"><span>From</span><span>To</span><span>Amount</span></div>${sample.model_input.asset_transfers.map(t=>`<div class="payment-row">${securityAccount(t.from)}${securityAccount(t.to)}<strong>${securityNumber(t.amount)} <small>${esc(t.asset)}</small></strong></div>`).join('')}</div></div>
 <div class="security-steps" role="group" aria-label="Scenario steps">${copy.steps.map(([title],i)=>`<button data-security-step="${i}" aria-pressed="${i===securityStep}"><span>${String(i+1).padStart(2,'0')}</span><strong>${title}</strong></button>`).join('')}</div><div class="security-step-detail"><span>${String(securityStep+1).padStart(2,'0')}</span><p>${copy.steps[securityStep][1]}</p></div></section>
 <div class="security-bottom"><section class="security-panel"><div class="panel-title"><h2>Balance changes</h2><span class="small">Before → After</span></div><div class="security-balances"><table><thead><tr><th>Account</th><th>Asset</th><th>Before</th><th>After</th><th>Change</th></tr></thead><tbody>${sample.display.balances_before_after.map(b=>`<tr><td>${securityAccount(b.actor)}</td><td>${esc(b.asset)}</td><td>${securityNumber(b.before)}</td><td>${securityNumber(b.after)}</td><td class="${Number(b.delta)>0?'balance-up':Number(b.delta)<0?'balance-down':'balance-flat'}">${Number(b.delta)>0?'+':''}${securityNumber(b.delta)}</td></tr>`).join('')}</tbody></table></div>${group.id==='price_manipulation'?'<p class="balance-note">Cash balances exclude the collateral claim and outstanding debt shown above.</p>':''}</section>
 <aside class="security-panel security-context"><h2>Key safeguards</h2><div class="security-safeguard"><span>Failure mechanism</span><p>${insight.failure}</p><span>Control to enforce</span><p>${insight.control}</p></div><dl><div><dt>Calls / transfers</dt><dd>${sample.model_input.call_trace.length} / ${sample.model_input.asset_transfers.length}</dd></div></dl><details class="security-source"><summary>HSK source transaction</summary><p>Operation template only · Not attack evidence</p><a href="${securitySourceURL(group)}" target="_blank" rel="noopener">${short(group.source_transaction.hash)} ↗</a><div class="source-facts"><span>${esc(group.source_transaction.method)}</span><span>Block ${securityNumber(group.source_transaction.block)}</span><span>${securitySourceDate(group.source_transaction.timestamp)}</span></div><details><summary>Original snapshot</summary><pre>${esc(englishRaw(group.source_transaction.original_state))}</pre></details></details></aside></div>
 <details class="security-events security-panel"><summary>Scenario events <span>${securityEvents(sample).length}</span></summary><div class="security-event-table"><table><thead><tr><th>Time · UTC</th><th>Type</th><th>Operation</th><th>Value / Result</th></tr></thead><tbody>${securityEvents(sample).map(e=>`<tr><td class="event-time">${securityEventClock(sample,e.order)}<small>#${String(e.order).padStart(2,'0')}</small></td><td><span class="event-kind">${e.kind}</span></td><td>${esc(securityText(e.operation))}</td><td class="${e.flag?'balance-down':''}">${esc(securityText(e.value))}</td></tr>`).join('')}</tbody></table></div></details>
`;
 document.querySelectorAll('[data-security-variant]').forEach(b=>b.onclick=()=>openSecurityCase(group.id+'-'+b.dataset.securityVariant));
 document.querySelectorAll('[data-security-step]').forEach(b=>b.onclick=()=>{securityStep=Number(b.dataset.securityStep);document.querySelectorAll('[data-security-step]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('.security-step-detail').innerHTML=`<span>${String(securityStep+1).padStart(2,'0')}</span><p>${copy.steps[securityStep][1]}</p>`});
 }
const securityInsights={
 reentrancy:{failure:'External callbacks execute while withdrawal credit is still available.',control:'Update credit before transferring funds; block nested withdrawals.'},
 faulty_access_control:{failure:'Failed caller and recipient checks do not stop the transfer.',control:'Revert when the caller lacks permission or the recipient violates policy.'},
 price_manipulation:{failure:'The lender accepts a pool price that the borrower just changed.',control:'Use an independent price source and reject borrowing against a transient price move.'}
};
async function renderSecurityEvaluation(){
 const root=$('#security-evaluation-content');
 try{await loadSecurityData()}catch{root.innerHTML='<p class="small">Unable to load security scenarios.</p>';return}
 const all=securityData.groups.flatMap(g=>g.variants.map(v=>({g,v}))),entry=all.find(x=>x.v.id===securityEvaluationCase)||all[0],sample=entry.v,draft=securityEdits.get(sample.id);securityEvaluationCase=sample.id;
 root.innerHTML=`<div class="security-eval-toolbar"><label>Scenario<select id="security-eval-case">${all.map(({g,v})=>`<option value="${v.id}" ${v.id===sample.id?'selected':''}>${securityPatterns[g.id].name} · ${v.variant==='attack'?'Attack variant':'Baseline'}</option>`).join('')}</select></label><span class="model-state">Jev <span>${sample.model_result===null?'Not run':'Available'}</span></span></div><p class="small">6 synthetic scenarios · Authored labels · No security accuracy score</p><div class="annotation-grid"><div><h3>Case labels</h3><div class="security-label-options">${Object.entries(securityPatterns).map(([id,p])=>`<label><input type="checkbox" data-security-label="${id}" ${draft.attack_labels.includes(id)?'checked':''}>${p.name}</label>`).join('')}</div><p class="small">Session edits · Export to save</p></div><div><label class="case-notes">Notes<textarea id="security-notes" rows="3" placeholder="Add a case note">${esc(draft.notes)}</textarea></label><div class="annotation-actions"><button id="security-reset-labels">Reset to preset</button><button id="security-export-labels" class="download-button">↓ Export annotations</button></div></div></div><div class="security-eval-download"><button class="download-button" id="security-input-download">↓ Model input</button></div><details><summary>Model input</summary><pre>${esc(englishRaw(sample.model_input))}</pre></details>`;
 $('#security-eval-case').onchange=e=>{securityEvaluationCase=e.target.value;renderSecurityEvaluation()};
 root.querySelectorAll('[data-security-label]').forEach(b=>b.onchange=()=>{draft.attack_labels=[...root.querySelectorAll('[data-security-label]:checked')].map(x=>x.dataset.securityLabel)});
 $('#security-notes').oninput=e=>draft.notes=e.target.value;
 $('#security-reset-labels').onclick=()=>{securityEdits.set(sample.id,{attack_labels:[...sample.reference_annotation.attack_labels],notes:''});renderSecurityEvaluation()};
 $('#security-input-download').onclick=()=>securityDownload(sample.id+'-input.json',sample.model_input);
 $('#security-export-labels').onclick=()=>securityDownload('hsk-security-annotations.json',{schema_version:securityData.schema_version,origin:'synthetic_counterfactual',exported_at:new Date().toISOString(),annotation_policy:'Authored scenarios and session edits; not model predictions or validation results.',cases:all.map(({g,v})=>({id:v.id,group_id:g.id,variant:v.variant,source_transaction_hash:g.source_transaction.hash,reference_annotation:v.reference_annotation,edited_annotation:{...securityEdits.get(v.id),author:'page_editor'},model_result:v.model_result}))});
}
$('#security-evaluation').addEventListener('toggle',()=>{if($('#security-evaluation').open)renderSecurityEvaluation()});

function securityMetrics(g,s){const st=s.model_input.post_state.storage,tr=s.model_input.asset_transfers;
 if(g.id==='reentrancy')return [{label:'Authorized credit',value:s.model_input.pre_state.storage['credit.actor_a'],unit:'HSK'},{label:'Total paid',value:tr.reduce((a,t)=>a+Number(t.amount),0),unit:'HSK'},{label:'Excess withdrawal',value:s.display.metrics[1].value,unit:'HSK'}];
 if(g.id==='faulty_access_control')return [{label:'Funds transferred',value:tr[0].amount,unit:'HSK'},{label:'Treasury remaining',value:s.model_input.post_state.balances.toy_treasury.HSK,unit:'HSK'},{label:'Unenforced checks',value:s.model_input.control_checks.filter(c=>!c.enforced).length,unit:'of 2'}];
 return [{label:'Outstanding debt',value:st['position.debt_usdt'],unit:'USDT'},{label:'Collateral reference value',value:Number(st['position.collateral_hsk'])*Number(st.reference_price_usdt_per_hsk),unit:'USDT',note:'Assumed price · 100 USDT/HSK'},{label:'Cash remaining',value:s.model_input.post_state.balances.actor_a.USDT,unit:'USDT',note:'Cash balance, before debt'}];
}
function securityDiagram(g,s,p){const attack=s.variant==='attack',c=p.color,good='#5e9687',bad='#b77783';let inner='';
 if(g.id==='reentrancy'){
  const tr=s.model_input.asset_transfers,events=securityEvents(s),last=events.at(-1).order,x=o=>190+o/last*770,writes=s.model_input.storage_accesses.filter(e=>e.operation==='write'),first=writes[0].order;
  inner=`<text x="20" y="38" class="diagram-label">Credit</text><path d="M190 33H${x(first)}V70H960" fill="none" stroke="${c}" stroke-width="3"/><text x="197" y="23" class="diagram-value">10 HSK</text><text x="${Math.min(915,x(first)+12)}" y="91" class="diagram-label">0 HSK</text><text x="20" y="132" class="diagram-label">${securityActor('toy_vault')}</text><text x="20" y="233" class="diagram-label">${securityActor('actor_a')}</text><path d="M190 128H960M190 229H960" stroke="#dfe6ef"/>`;
  tr.forEach((t,i)=>{const xx=x(t.order);inner+=`<path d="M${xx} 135V216" stroke="${c}" stroke-width="2" marker-end="url(#security-arrow)"/><circle cx="${xx}" cy="128" r="5" fill="${c}"/><rect x="${xx-38}" y="164" width="76" height="27" rx="5" fill="#f1eef6"/><text x="${xx}" y="182" text-anchor="middle" class="diagram-value">${securityNumber(t.amount)} HSK</text><text x="${xx}" y="262" text-anchor="middle" class="diagram-label">Payment ${i+1}</text>`});
  inner+=`<text x="960" y="307" text-anchor="end" class="diagram-label">${attack?'Credit cleared after all three payments':'Credit cleared before payment'} · Event order →</text>`;
 }else if(g.id==='faulty_access_control'){
  const checks=s.model_input.control_checks,tr=s.model_input.asset_transfers[0];inner=`<path d="M154 159H228M228 159V107H252M228 159V227H252M472 107H502V159H598M472 227H502V159M770 159H866" fill="none" stroke="#cbd6e3" stroke-width="2" marker-end="url(#security-arrow)"/><rect x="20" y="122" width="134" height="74" rx="12" fill="#f2f5f9"/><text x="87" y="153" text-anchor="middle" class="diagram-label">Caller</text><text x="87" y="176" text-anchor="middle" class="diagram-address">${securityActor(s.model_input.transaction.from)}</text>`;
  checks.forEach((check,i)=>{const yy=65+i*120,col=check.enforced?good:bad;inner+=`<rect x="252" y="${yy}" width="220" height="85" rx="10" fill="${col}0d" stroke="${col}40"/><text x="270" y="${yy+27}" class="diagram-value">${i?'Approved recipient':'Authorized caller'}</text><text x="270" y="${yy+53}" class="diagram-label">${check.observed_value?'Passed':'Failed'} · ${check.enforced?'Enforced':'Bypassed'}</text>`});
  inner+=`<rect x="598" y="122" width="172" height="74" rx="12" fill="#f4f1ed"/><text x="684" y="151" text-anchor="middle" class="diagram-label">Treasury transfer</text><text x="684" y="177" text-anchor="middle" class="diagram-value">${securityNumber(tr.amount)} HSK</text><text x="934" y="151" text-anchor="middle" class="diagram-label">Recipient</text><text x="934" y="177" text-anchor="middle" class="diagram-address">${securityActor(tr.to)}</text><text x="510" y="296" text-anchor="middle" class="diagram-label">${attack?'Both constraints fail; the transfer still executes.':'Caller and recipient satisfy the policy.'}</text>`;
 }else{
  const st=s.model_input.post_state.storage,initial=100,peak=attack?400:100,final=Number(st['pool.reserve_usdt'])/Number(st['pool.reserve_hsk']),debt=Number(st['position.debt_usdt']),value=Number(st['position.collateral_hsk'])*100,y=v=>232-v/400*180;
  inner=`<text x="24" y="29" class="diagram-label">Pool spot price · USDT / HSK</text><path d="M65 232H550" stroke="#dde5ef"/><path d="M80 ${y(initial)}L305 ${y(peak)}L530 ${y(final)}" fill="none" stroke="${c}" stroke-width="2.5" stroke-linejoin="round"/>`;
  [[80,initial,'Before'],[305,peak,'At borrowing'],[530,final,'After']].forEach(([x,v,label])=>{inner+=`<circle cx="${x}" cy="${y(v)}" r="5" fill="white" stroke="${c}" stroke-width="2"/><text x="${x}" y="${y(v)-15}" text-anchor="middle" class="diagram-value">${Number(v.toFixed(2))}</text><text x="${x}" y="264" text-anchor="middle" class="diagram-label">${label}</text>`});
  const max=Math.max(debt,value);inner+=`<path d="M620 30V274" stroke="#e5eaf1"/><text x="660" y="58" class="diagram-label">Outstanding debt</text><rect x="660" y="79" width="${debt/max*280}" height="7" rx="3" fill="${attack?bad:c}"/><text x="660" y="116" class="diagram-value">${securityNumber(debt)} USDT</text><text x="660" y="166" class="diagram-label">Collateral at reference price</text><rect x="660" y="187" width="${value/max*280}" height="7" rx="3" fill="${good}"/><text x="660" y="224" class="diagram-value">${securityNumber(value)} USDT</text><text x="660" y="278" class="diagram-label">${attack?'20,000 USDT valuation gap':'50% loan-to-value'}</text><text x="24" y="307" class="diagram-label">${attack?'Spot-price borrowing · No liquidation simulated':'Borrowing uses the independent reference price'}</text>`;
 }
 return `<svg class="mechanism-illustration" viewBox="0 0 1020 325" role="img" aria-label="${esc(p.name)} ${attack?'attack':'baseline'} mechanism"><defs><linearGradient id="mechanism-surface" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#ffffff"/><stop offset="1" stop-color="${c}" stop-opacity=".11"/></linearGradient><filter id="mechanism-shadow" x="-20%" y="-50%" width="140%" height="220%"><feDropShadow dx="0" dy="6" stdDeviation="8" flood-color="${c}" flood-opacity=".10"/></filter><marker id="security-arrow" viewBox="0 0 8 8" refX="6" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L8 4L0 8" fill="${c}"/></marker></defs>${inner.replaceAll('rx="12" fill=','rx="12" filter="url(#mechanism-shadow)" fill=').replaceAll('rx="10" fill=','rx="10" filter="url(#mechanism-shadow)" fill=')}</svg>`;
}
function securityEvents(s){const i=s.model_input;return [...i.call_trace.map(e=>({order:e.order,kind:'Call',operation:`${securityActor(e.from)} → ${securityActor(e.to)} · ${e.method}`,value:JSON.stringify(e.arguments)})),...i.storage_accesses.map(e=>({order:e.order,kind:e.operation==='read'?'Read':'Write',operation:e.key,value:e.operation==='read'?JSON.stringify(e.value):JSON.stringify(e.before)+' → '+JSON.stringify(e.after)})),...i.control_checks.map(e=>({order:e.order,kind:'Check',operation:e.expression,value:`${JSON.stringify(e.observed_value)} · ${e.enforced?'Enforced':'Bypassed'}`,flag:!e.enforced})),...i.asset_transfers.map(e=>({order:e.order,kind:'Transfer',operation:`${securityActor(e.from)} → ${securityActor(e.to)}`,value:`${securityNumber(e.amount)} ${e.asset}`}))].sort((a,b)=>a.order-b.order)}
function securityDownload(filename,payload){const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
